`timescale 1ns / 1ps

module argmax10 #(
    parameter integer WIDTH = 16
)(
    input  wire signed [WIDTH-1:0] in0,
    input  wire signed [WIDTH-1:0] in1,
    input  wire signed [WIDTH-1:0] in2,
    input  wire signed [WIDTH-1:0] in3,
    input  wire signed [WIDTH-1:0] in4,
